import java.util.Scanner;

class Member {
    private String nim;
    private String name;

    Member(String name) {
        this.name = name;
    }

    String getNim() {
        return nim;
    }

    void setNim(String nim) {
        // Tolak NIM yang null atau bukan tepat 10 digit angka: lempar IllegalArgumentException dengan pesan "NIM harus 10 digit angka: <nim>". Bila benar, simpan.
        this.nim = nim;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        Member m = new Member(in.nextLine().trim());
        while (in.hasNextLine()) {
            String line = in.nextLine().trim();
            if (line.equals("selesai")) {
                break;
            }
            try {
                m.setNim(line);
                System.out.println("NIM diterima: " + m.getNim());
            } catch (IllegalArgumentException e) {
                System.out.println("Ditolak: " + e.getMessage());
            }
        }
        System.out.println("NIM tersimpan: " + (m.getNim() == null ? "belum ada" : m.getNim()));
    }
}
